/* Five private, practical workbenches. Media never leaves this browser session. */
const DISCIPLINES = ['writer', 'mc', 'dj', 'breaking', 'knowledge'];
const LABELS = {writer:'LETTERS INTO IDENTITY',mc:'FIND YOUR OWN VOICE',dj:'SOUND ARCHAEOLOGY',breaking:'READ THE RHYTHM',knowledge:'KNOWLEDGE OF SELF'};
const COLORS = ['#FFD600','#F5F1E8','#E71932','#080808'];
const MAX_POINTS = 12000;
const e = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const copy = value => JSON.parse(JSON.stringify(value));
const uid = () => globalThis.crypto?.randomUUID?.() || `w-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const clamp = (n,min,max) => Math.max(min,Math.min(max,n));
const nonempty = text => String(text || '').trim().length > 0;
export function lineCount(text) { return String(text || '').split(/\r?\n/).filter(s=>s.trim()).length; }
export function markedText(text) {
  // Deliberately literal: user markup cannot become executable HTML.
  return String(text || '').split(/(\|[^|\n]+\||\/)/).map(part => part === '/' ? '<span class="ws-breath" aria-label="nádech"> / </span>' : /^\|[^|]+\|$/.test(part) ? `<strong class="ws-accent">${e(part.slice(1,-1))}</strong>` : e(part)).join('');
}
export function normalizeStrokes(strokes) {
  let remaining = MAX_POINTS;
  return (Array.isArray(strokes) ? strokes : []).slice(0,180).map(stroke => {
    const points = (Array.isArray(stroke?.points) ? stroke.points : []).filter(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)).slice(0,remaining).map(p=>[clamp(p[0],0,900),clamp(p[1],0,440)]);
    remaining -= points.length;
    return {points,color:COLORS.includes(stroke?.color)?stroke.color:COLORS[0],width:clamp(Number(stroke?.width)||8,2,32)};
  }).filter(s=>s.points.length);
}
export function strokePath(points) { const path=points.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join(' ');return points.length===1?`${path} l0.1 0.1`:path; }
export function buildWorkText(discipline,draft) {
  if(discipline==='writer') return [draft.word||'Návrh',draft.text||'',`Paleta: ${(draft.palette||[]).map(x=>`${x.color} — ${x.purpose}`).join('; ')}`,`Povolená realizace: ${draft.legal||'Neplánována — digitální skica.'}`,`Tahů: ${(draft.strokes||[]).length}`].join('\n');
  if(discipline==='dj') return [`Záměr: ${draft.text||''}`,`Tracklist:\n${draft.tracklist||''}`,`Energie: ${(draft.energy||[]).join(' → ')}`,`Cue a rozhodnutí:\n${draft.cues||''}`,`Obal / název: ${draft.title||''}`,`Srovnání přechodu: ${draft.compare||''}`].join('\n');
  if(discipline==='breaking') return [`Úroveň: ${draft.level||'vlastní pozorování'}`,`Záměr: ${draft.text||''}`,`Vlastní fráze: ${draft.phrase||''}`,`Hudební podnět: ${draft.cue||''}`,`Podmínky session: ${draft.session||''}`,`Skutečná zpětná vazba: ${draft.feedback||'Zatím nedodaná.'}`,`Druhé provedení / rozdíl: ${draft.compare||''}`].join('\n');
  if(discipline==='knowledge') return [`Pozorování: ${draft.observation||''}`,`Doložená informace: ${draft.fact||''}`,`Zdroj: ${draft.source||''}`,`Interpretace: ${draft.interpretation||''}`,`První manifest:\n${draft.text||''}`,`Zpřesněný manifest:\n${draft.refined||''}`,`Symbol: ${draft.symbol||''} — ${draft.meaning||''}`,`Protiotázka / hranice: ${draft.counter||''}`].join('\n');
  return [draft.text||'',`Záměr přednesu A: ${draft.takeA||''}`,`Záměr přednesu B: ${draft.takeB||''}`,`Původní řádek: ${draft.oldLine||''}`,`Upravený řádek: ${draft.newLine||''}`,`Metafora: ${draft.detail||''} → ${draft.association||''} → ${draft.meaning||''}`].join('\n');
}
export function validateWork(discipline,draft) {
  if(!DISCIPLINES.includes(discipline)) return 'Neznámá disciplína.';
  if(!nonempty(draft.decision)) return 'Popiš alespoň jedno vlastní rozhodnutí; samotné odškrtnutí není výsledek.';
  if(!nonempty(draft.nextStep)) return 'Napiš jeden konkrétní další krok.';
  if(discipline==='writer' && !normalizeStrokes(draft.strokes).length) return 'Nejdřív vytvoř alespoň jeden vlastní tah.';
  if(discipline==='writer' && !(draft.palette||[]).some(p=>nonempty(p.purpose))) return 'Připiš funkci alespoň jedné barvy v návrhu.';
  if(discipline==='mc' && lineCount(draft.text)<(draft.target==='16'?16:4)) return draft.target==='16'?'Pro zvolené zadání napiš šestnáct vlastních řádků.':'Napiš nejméně čtyři vlastní řádky.';
  if(discipline==='dj' && lineCount(draft.tracklist)<3) return 'Připrav tracklist alespoň tří skladeb.';
  if(discipline==='dj' && !nonempty(draft.cues)) return 'Přidej konkrétní nástup, výstup nebo rozhodnutí k přechodu.';
  if(discipline==='breaking' && (!nonempty(draft.phrase)||!nonempty(draft.session))) return 'Popiš vlastní frázi a podmínky bezpečné session.';
  if(discipline==='knowledge' && nonempty(draft.fact)&&!nonempty(draft.source)) return 'K doložené informaci přidej zdroj; vlastní interpretaci ponech odděleně.';
  if(discipline==='knowledge' && (!nonempty(draft.observation)||!nonempty(draft.interpretation)||!nonempty(draft.refined))) return 'Odděl pozorování, interpretaci a zpřesněný manifest.';
  return null;
}
function initial(discipline) {
  const base={title:'',text:'',decision:'',nextStep:''};
  if(discipline==='writer') return {...base,word:'',strokes:[],palette:COLORS.slice(0,3).map((color,i)=>({color,purpose:['dominanta','kontrast','akcent'][i]})),legal:'',alphabet:{},layer:'all',scale:'1'};
  if(discipline==='mc') return {...base,target:'4',takeA:'',takeB:'',oldLine:'',newLine:'',detail:'',association:'',meaning:''};
  if(discipline==='dj') return {...base,tracklist:'',energy:[2,4,6,8,5],cues:'',compare:''};
  if(discipline==='breaking') return {...base,level:'pozorování',phrase:'',cue:'',session:'',feedback:'',compare:''};
  return {...base,observation:'',fact:'',source:'',interpretation:'',refined:'',symbol:'◉',meaning:'',counter:''};
}
// Apply only edits made by this mounted workbench. Untouched fields can belong
// to another tab; a stale whole-module snapshot must never replace them.
export function applyWorkshopDelta(target,before,after) {
  const plain=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
  for(const key of new Set([...Object.keys(before||{}),...Object.keys(after||{})])){
    if(['__proto__','constructor','prototype'].includes(key))continue;
    if(!Object.hasOwn(after,key)){if(Object.hasOwn(before,key))delete target[key];continue;}
    if(JSON.stringify(before?.[key])===JSON.stringify(after[key]))continue;
    if(plain(before?.[key])&&plain(after[key])){
      if(!plain(target[key]))target[key]={};
      applyWorkshopDelta(target[key],before[key],after[key]);
    }else target[key]=copy(after[key]);
  }
  return target;
}
export function normalizeDraft(discipline,value) {
  const output=initial(discipline), plain=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
  if(!plain(value))return output;
  for(const [key,defaultValue] of Object.entries(output))if(typeof defaultValue==='string'&&typeof value[key]==='string')output[key]=value[key].slice(0,12000);
  if(typeof value.artifactId==='string'&&value.artifactId.length<150)output.artifactId=value.artifactId;
  if(discipline==='writer'){
    output.strokes=normalizeStrokes(value.strokes);
    if(Array.isArray(value.palette))output.palette=value.palette.slice(0,3).map((p,i)=>({color:COLORS.includes(p?.color)?p.color:COLORS[i],purpose:typeof p?.purpose==='string'?p.purpose.slice(0,200):''}));
    if(!output.palette.length)output.palette=initial('writer').palette;
    if(plain(value.alphabet))output.alphabet=Object.fromEntries(Object.entries(value.alphabet).filter(([k,v])=>k.length<=4&&Array.isArray(v)).slice(0,40).map(([k,v])=>[k,normalizeStrokes(v)]));
    if(!['all','skeleton','outline','fill','negative'].includes(output.layer))output.layer='all';
    if(!['1','0.45','1.65'].includes(output.scale))output.scale='1';
  }
  if(discipline==='mc'&&!['4','16'].includes(output.target))output.target='4';
  if(discipline==='dj'){
    output.energy=Array.from({length:5},(_,i)=>Number.isFinite(value.energy?.[i])?clamp(value.energy[i],0,10):initial('dj').energy[i]);
    for(const key of ['pointA','pointB'])if(Number.isFinite(value[key])&&value[key]>=0)output[key]=value[key];
  }
  if(discipline==='breaking'&&!['pozorování','začínám s lektorem','vlastní zkušenost s bezpečnou frází'].includes(output.level))output.level='pozorování';
  if(discipline==='knowledge')output.symbol=output.symbol.slice(0,4);
  return output;
}
const field=(name,label,value,rows=3,placeholder='')=>`<label class="ws-field"><span>${label}</span><textarea data-field="${name}" rows="${rows}" maxlength="12000" placeholder="${e(placeholder)}">${e(value)}</textarea></label>`;
const input=(name,label,value,max=150)=>`<label class="ws-field"><span>${label}</span><input data-field="${name}" value="${e(value)}" maxlength="${max}"></label>`;

export function mountWorkshops(root,{store,notify=()=>{}}) {
  const controller=new AbortController(), signal=controller.signal;
  const reduced=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)')||{matches:false};
  const saved=store.get().drafts?.workshops;
  let active=DISCIPLINES.includes(saved?.active)?saved.active:'writer';
  const drafts=Object.fromEntries(DISCIPLINES.map(id=>[id,normalizeDraft(id,saved?.[id])]));
  drafts.writer.strokes=normalizeStrokes(drafts.writer.strokes);
  let baseline={active,...copy(drafts)};
  let dirty=false,timer=null,replayFrame=null,stroke=null,pointer=null,keyboardPoint=[450,220],recording=null,stream=null,recordToken=0,disposed=false;
  const media=new Map(),urls=new Set(),disposers=[];
  const listen=(node,type,fn,options={})=>{if(!node)return;node.addEventListener(type,fn,{...options,signal});disposers.push(()=>node.removeEventListener(type,fn,options));};
  function flush(){clearTimeout(timer);if(!dirty)return;const snapshot={active,...copy(drafts)};if(JSON.stringify(snapshot)===JSON.stringify(baseline)){dirty=false;return;}const ok=store.update(s=>{s.drafts.workshops=applyWorkshopDelta(s.drafts.workshops||{},baseline,snapshot);});if(ok){baseline=copy(snapshot);dirty=false;}}
  function schedule(){dirty=true;clearTimeout(timer);timer=setTimeout(flush,400);}
  function feedback(text){const target=root.querySelector('.ws-status');if(target)target.textContent=text;notify(text);}
  function releaseMedia(key){const item=media.get(key);if(item){if(item.element){item.element.pause();item.element.removeAttribute('src');item.element.load();}URL.revokeObjectURL(item.url);urls.delete(item.url);media.delete(key);}}
  function stopRecording(){if(recording&&recording.state!=='inactive')recording.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;}
  function stopReplay(){if(replayFrame!==null)cancelAnimationFrame(replayFrame);replayFrame=null;const b=root.querySelector('[data-action="replay"]');if(b)b.textContent='PŘEHRÁT SKUTEČNÉ TAHY';}
  function button(action,text){return `<button type="button" data-action="${action}">${text}</button>`;}
  function writerPanel(d){return `<div class="ws-two"><div><p class="ws-kicker">01 / KONSTRUKCE → VLASTNÍ TAH → REVIZE</p>${input('word','Vlastní slovo / písmeno',d.word,40)}<div class="ws-drawing-tools"><label>Nástroj <select data-tool="width"><option value="4">Tenký / 4</option><option value="10" selected>Střední / 10</option><option value="22">Široký / 22</option></select></label><label>Barva <select data-tool="color">${COLORS.map(c=>`<option value="${c}">${c}</option>`).join('')}</select></label><label>Rozbor <select data-field="layer">${[['all','Celá kompozice'],['skeleton','Osa'],['outline','Obrys'],['fill','Výplň'],['negative','Negativní prostor']].map(([v,l])=>`<option value="${v}" ${d.layer===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Měřítko <select data-field="scale">${[['1','Celek'],['0.45','Pohled z dálky'],['1.65','Detail']].map(([v,l])=>`<option value="${v}" ${d.scale===v?'selected':''}>${l}</option>`).join('')}</select></label></div><svg class="ws-sketch" viewBox="0 0 900 440" role="img" aria-label="Vlastní digitální skica. Myší nebo prstem kresli. Klávesnice: šipky posouvají bod, mezerník zahájí a ukončí tah." tabindex="0"><title>Vlastní digitální skica</title><defs><pattern id="ws-grid" width="45" height="44" patternUnits="userSpaceOnUse"><path d="M45 0H0V44" fill="none" stroke="#4a4430" stroke-width="1"/></pattern></defs><rect width="900" height="440" fill="#101010"/><rect width="900" height="440" fill="url(#ws-grid)"/><g data-strokes></g><circle data-cursor cx="450" cy="220" r="7" fill="#F5F1E8" stroke="#080808" stroke-width="3" opacity="0"/></svg><p class="ws-help">Kresli prstem či myší. Klávesnice: šipky posouvají bod, mezerník začne/ukončí tah. Escape tah dokončí. Negativní prostor je vizuální převrácení vlastní skici, nikoli automatické hodnocení.</p><div class="ws-actions">${button('undo','ZPĚT JEDEN TAH')}${button('replay','PŘEHRÁT SKUTEČNÉ TAHY')}${button('stopReplay','ZASTAVIT')}${button('downloadSvg','EXPORT SVG')}${button('clear','SMAZAT SKICU')}</div><div class="ws-actions">${button('alphabet','ULOŽIT PÍSMENO DO ABECEDY')}<span class="ws-alphabet">${Object.keys(d.alphabet||{}).map(letter=>`<button type="button" data-letter="${e(letter)}" aria-label="Načíst vlastní písmeno ${e(letter)}">${e(letter)}</button>`).join(' ')||'Tvoje vlastní abeceda'}</span></div></div><div><p class="ws-kicker">02 / PALETA S FUNKCÍ</p>${d.palette.map((p,i)=>`<label class="ws-palette"><span style="background:${COLORS.includes(p.color)?p.color:'#FFD600'}"></span><select data-palette-color="${i}" aria-label="Barva ${i+1}">${COLORS.map(c=>`<option ${p.color===c?'selected':''}>${c}</option>`).join('')}</select><input data-palette="${i}" aria-label="Funkce barvy ${i+1}" value="${e(p.purpose)}" maxlength="200"></label>`).join('')}${field('text','Co má být čitelné a z jaké vzdálenosti?',d.text)}${field('legal','Plán povolené realizace',d.legal,5,'Konkrétní plocha, správce, souhlas / pravidla, příprava, rozměr a pracovní čas. Digitální návrh sám o sobě nedává souhlas malovat.')}<p class="ws-help">Náhled je původní digitální skica v měřítku 900 × 440. Nenahrazuje fotografii skutečné zdi ani povolení.</p></div></div>`;}
  function mediaSlot(key,label,type='audio'){const item=media.get(key);return `<div class="ws-media-slot"><h4>${label}</h4>${item?`<${type} controls preload="metadata" data-media="${key}" src="${e(item.url)}" ${type==='video'?'playsinline':''}></${type}><a href="${e(item.url)}" download="${e(item.name)}">STÁHNOUT VLASTNÍ SOUBOR ↓</a> ${button('delete-'+key,'SMAZAT Z TÉTO RELACE')}`:'<p class="ws-help">Zatím žádný vlastní záznam.</p>'}</div>`;}
  function mcPanel(d){const inventory=(store.get().inventory||[]).slice(-25);return `<div class="ws-two"><div><p class="ws-kicker">01 / KONKRÉTNÍ OBRAZ → ČTYŘI BARY → VLASTNÍ HLAS</p><label class="ws-field"><span>Zadání</span><select data-field="target"><option value="4" ${d.target==='4'?'selected':''}>4 bary / krátký obraz</option><option value="16" ${d.target==='16'?'selected':''}>16 barů / rozvinutá sloka</option></select></label>${field('text','Vlastní text. / označí nádech, |slovo| označí důraz.',d.text,10,'Konkrétní detail, zvuk, gesto. Jeden bar na řádek.')}<p class="ws-count">${lineCount(d.text)} řádků / záměr ${e(d.target)}. Počet řádků není skóre kvality.</p><div class="ws-reading" data-reading>${markedText(d.text)||'Tvůj přednes dostane vlastní rytmus.'}</div>${button('drawWords','VYLOSUJ TŘI PODNĚTY Z INVENTÁŘE')}<p data-prompts data-i18n-user>${inventory.length?'Losují se tvoje vlastní uložené materiály.':'Nejdřív si ulož slova nebo postřehy do inventáře.'}</p></div><div>${field('oldLine','Původní řádek',d.oldLine,2)}${field('newLine','Přesnější vlastní varianta',d.newLine,2)}${button('replaceLine','NAHRADIT PŘESNOU SHODU V TEXTU')}${input('detail','Pozorovaný detail',d.detail,300)}${input('association','Vzdálená asociace',d.association,300)}${input('meaning','Co tím chci sdělit',d.meaning,300)}<p class="ws-help">Nejde o automatický generátor slok. Spojení a konečný řádek rozhoduješ ty.</p></div></div><div class="ws-recording"><p class="ws-kicker">02 / DVA VLASTNÍ PŘEDNESY, STEJNÝ TEXT</p><p>Zvuk zůstává pouze v paměti této otevřené stránky. Po reloadu zmizí. Stáhni si ho, chceš-li jej zachovat. Mikrofon se žádá teprve po stisku nahrávání; žádný upload.</p><div class="ws-two"><div>${field('takeA','Záměr verze A',d.takeA,2)}<div class="ws-actions">${button('record-A','NAHRÁT A')}<label class="ws-file">Nahrát vlastní A<input type="file" data-file="takeA" accept="audio/*"></label></div>${mediaSlot('takeA','PŘEDNES A')}</div><div>${field('takeB','Záměr verze B / konkrétní změna',d.takeB,2)}<div class="ws-actions">${button('record-B','NAHRÁT B')}<label class="ws-file">Nahrát vlastní B<input type="file" data-file="takeB" accept="audio/*"></label></div>${mediaSlot('takeB','PŘEDNES B')}</div></div>${button('stopRecord','ZASTAVIT NAHRÁVÁNÍ A UVOLNIT MIKROFON')}<p class="ws-record-status" role="status"></p></div>`;}
  function djPanel(d){return `<div class="ws-two"><div><p class="ws-kicker">01 / VÝBĚR → DRAMATURGIE → TŘI ROZHODNUTÍ</p>${field('text','Jaký příběh / funkci má krátký set?',d.text)}${field('tracklist','Vlastní tracklist — alespoň tři skladby, autor a záměr',d.tracklist,7,'Autor — skladba — proč je tady\nAutor — skladba — co navazuje\nAutor — skladba — jak zakončí')}<p class="ws-help">Odkaz na skladbu nedává licenci k jejímu veřejnému šíření. Zde pracuješ soukromě se svým nebo oprávněně použitým materiálem.</p><h4>Mapa zamýšlené energie</h4><svg class="ws-energy" viewBox="0 0 500 120" role="img" aria-label="Vlastní pětibodová mapa energie"><path data-energy-line fill="none" stroke="#FFD600" stroke-width="4"/><g data-energy-dots></g></svg><div class="ws-energy-inputs">${d.energy.map((n,i)=>`<label>Bod ${i+1}<input type="range" min="0" max="10" value="${n}" data-energy="${i}" aria-label="Zamýšlená energie bodu ${i+1}"></label>`).join('')}</div></div><div>${field('cues','Cue body, nástupy / výstupy a tři vlastní rozhodnutí',d.cues,7,'00:00 — proč začínám tady\n00:32 — který prvek nechám zaznít\n01:15 — proč měním energii')}${field('compare','První a upravený přechod: co je slyšet jinak?',d.compare,4)}<label class="ws-file">Vybrat vlastní mix k soukromému poslechu<input type="file" data-file="mix" accept="audio/*"></label>${mediaSlot('mix','VLASTNÍ MIX')}<div class="ws-actions">${button('markCue','ZAPSAT AKTUÁLNÍ ČAS DO CUE')}${button('listenA','PAMATOVAT ČAS A')}${button('listenB','PAMATOVAT ČAS B')}${button('seekA','PŘEHRÁT OD A')}${button('seekB','PŘEHRÁT OD B')}</div><p class="ws-help">Soubor je pouze v této relaci. Nástroj nahrávku nesestříhá ani nevydává tracklist za hotový mix. Hotový mix vytvoříš svým DJ nástrojem a zde ho rozebereš.</p></div></div>`;}
  function breakingPanel(d){return `<div class="ws-two"><div><p class="ws-kicker">01 / BEZPEČNÝ VLASTNÍ ZÁMĚR → SESSION → POZOROVÁNÍ</p><label class="ws-field"><span>Výchozí zkušenost</span><select data-field="level">${['pozorování','začínám s lektorem','vlastní zkušenost s bezpečnou frází'].map(x=>`<option ${x===d.level?'selected':''}>${x}</option>`).join('')}</select></label>${field('text','Jeden záměr před pokusem',d.text)}${field('phrase','Vlastní přiměřená fráze / co už umím bezpečně',d.phrase,4)}${field('cue','Konkrétní hudební podnět / čas',d.cue,2)}${field('session','Příprava session: prostor, podlaha, vybavení, odborné vedení a pauzy',d.session,4)}<p class="ws-help">Ilustrace ani tento formulář nejsou odborná pohybová ukázka. Novou techniku, náročnost a vhodnost pokusu vybírej s kvalifikovaným lektorem. Můžeš zůstat u pozorování hudby a společného prostoru.</p></div><div><label class="ws-file">Vlastní záznam A<input type="file" data-file="phraseA" accept="video/*"></label>${mediaSlot('phraseA','VLASTNÍ PROVEDENÍ A','video')}<label class="ws-file">Vlastní záznam B<input type="file" data-file="phraseB" accept="video/*"></label>${mediaSlot('phraseB','VLASTNÍ PROVEDENÍ B','video')}${field('compare','Stejná fráze / jiný hudební podnět: co se změnilo?',d.compare)}${field('feedback','Skutečná připomínka lektora: kdo, kdy, k jakému momentu; nebo „zatím nemám“',d.feedback,4)}<p class="ws-help">Videa jsou jen v této relaci a neodesílají se. Text je vlastní reflexe; neprezentuje se jako automatická odborná zpětná vazba.</p></div></div>`;}
  function knowledgePanel(d){return `<div class="ws-two"><div><p class="ws-kicker">01 / CO VIDÍM ≠ CO DOKLÁDÁM ≠ JAK TO ČTU</p>${field('observation','Pozorování — co lze přímo popsat?',d.observation)}${field('fact','Doložená informace — konkrétní tvrzení',d.fact)}${input('source','Zdroj informace / přesná citace nebo URL',d.source,1000)}${field('interpretation','Vlastní interpretace — co z toho vyvozuji?',d.interpretation)}<p class="ws-help">Vložení URL samo o sobě neověřuje tvrzení. Oddělení těchto tří hlasů zachovej i ve výsledném textu.</p></div><div>${field('text','První manifest — až deset řádků',d.text,7)}${field('refined','Zpřesněný manifest — tři vlastní řádky',d.refined,4)}<p class="ws-count">První: ${lineCount(d.text)} / zpřesněný: ${lineCount(d.refined)} řádků.</p><div class="ws-symbol-row"><label class="ws-field"><span>Vlastní znak (nejvýše čtyři znaky)</span><input data-field="symbol" maxlength="4" value="${e(d.symbol)}"></label><span class="ws-personal-symbol" data-symbol>${e(d.symbol)}</span></div>${field('meaning','Význam jednotlivých částí symbolu',d.meaning)}${field('counter','Protiotázka: jak by to četl někdo jiný? Co chci chránit / nesdílet?',d.counter)}${button('useSymbol','POUŽÍT ZNAK JAKO SVŮJ AVATAR')}</div></div>`;}
  function render(){stopReplay();stopRecording();media.forEach(item=>item.element?.pause());root.innerHTML=`<section class="selfmade-workshop" aria-label="Vlastní tvůrčí dílny"><div class="ws-heading"><p class="ws-kicker">THE WORKBENCH / SELFMADE ONLY</p><h2>TVŮJ MATERIÁL.<br>TVŮJ VLASTNÍ TAH.</h2><p>První verze je začátek. Ulož vlastní pokus, pojmenuj rozhodnutí, uprav ho a sleduj skutečný rozdíl.</p></div><div class="ws-tabs" role="group" aria-label="Volba tvůrčí disciplíny">${DISCIPLINES.map(id=>`<button type="button" data-discipline="${id}" aria-pressed="${active===id}">${id==='knowledge'?'KNOWLEDGE':id.toUpperCase()}</button>`).join('')}</div><div class="ws-panel"><p class="ws-chapter">${LABELS[active]}</p>${input('title','Název vlastního projektu',drafts[active].title)}${active==='writer'?writerPanel(drafts.writer):active==='mc'?mcPanel(drafts.mc):active==='dj'?djPanel(drafts.dj):active==='breaking'?breakingPanel(drafts.breaking):knowledgePanel(drafts.knowledge)}<div class="ws-reflection"><p class="ws-kicker">03 / DŮKAZ JE TVOJE PRÁCE A VYSVĚTLENÁ ZMĚNA</p><div class="ws-two">${field('decision','Co a proč jsem rozhodl / co jsem změnil?',drafts[active].decision,4)}${field('nextStep','Jeden konkrétní další pokus',drafts[active].nextStep,4)}</div><div class="ws-actions">${button('save','ULOŽIT VERZI DO BLACKBOOKU')}${button('compare','POROVNAT PRVNÍ A POSLEDNÍ')}${button('newProject','NOVÝ PROJEKT')}</div><p class="ws-status" role="status" aria-live="polite">Texty a skici se průběžně ukládají lokálně. Média vyžadují vlastní stažení.</p><div data-comparison></div></div></div></section>`;draw();drawEnergy();bindMedia();}
  function bindMedia(){root.querySelectorAll('[data-media]').forEach(el=>{const m=media.get(el.dataset.media);if(m)m.element=el;});}
  function draw(limit=Infinity){const group=root.querySelector('[data-strokes]');if(!group)return;const d=drafts.writer,mode=d.layer,scale=Number(d.scale)||1;let left=limit;group.setAttribute('transform',`translate(${450*(1-scale)} ${220*(1-scale)}) scale(${scale})`);group.innerHTML=d.strokes.map(s=>{const points=s.points.slice(0,Math.max(0,left));left-=s.points.length;if(!points.length)return '';const path=strokePath(points),color=mode==='negative'?'#080808':s.color,width=mode==='skeleton'?2:mode==='outline'?s.width+7:s.width;return `${mode==='outline'?`<path d="${path}" fill="none" stroke="#F5F1E8" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round"/>`:''}<path d="${path}" fill="none" stroke="${color}" stroke-width="${mode==='outline'?s.width:width}" stroke-linecap="round" stroke-linejoin="round"/>`;}).join('');const bg=root.querySelector('.ws-sketch > rect');if(bg)bg.setAttribute('fill',mode==='negative'?'#FFD600':'#101010');}
  function drawEnergy(){const d=drafts.dj,points=d.energy.map((n,i)=>`${20+i*115},${108-n*9}`);root.querySelector('[data-energy-line]')?.setAttribute('d',points.map((p,i)=>`${i?'L':'M'}${p}`).join(' '));const dots=root.querySelector('[data-energy-dots]');if(dots)dots.innerHTML=points.map(p=>`<circle cx="${p.split(',')[0]}" cy="${p.split(',')[1]}" r="6" fill="#F5F1E8"/>`).join('');}
  function point(event){const svg=root.querySelector('.ws-sketch'),rect=svg.getBoundingClientRect();const scale=Number(drafts.writer.scale)||1;return [clamp(((event.clientX-rect.left)/rect.width*900-450*(1-scale))/scale,0,900),clamp(((event.clientY-rect.top)/rect.height*440-220*(1-scale))/scale,0,440)];}
  function startStroke(p){stopReplay();const total=drafts.writer.strokes.reduce((n,s)=>n+s.points.length,0);if(total>=MAX_POINTS||drafts.writer.strokes.length>=180){feedback('Limit skici: exportuj nebo ulož fázi a začni další projekt.');return false;}stroke={points:[p],color:root.querySelector('[data-tool="color"]')?.value||COLORS[0],width:Number(root.querySelector('[data-tool="width"]')?.value)||10};drafts.writer.strokes.push(stroke);return true;}
  function endStroke(){if(stroke){stroke=null;schedule();draw();}pointer=null;}
  function download(name,content,type){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);urls.add(url);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url);},30000);}
  async function record(slot){if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){feedback('Mikrofon v tomto prohlížeči není dostupný. Použij vlastní soubor nebo textové srovnání.');return;}if(recording?.state==='recording'){feedback('Nejdřív zastav probíhající nahrávání.');return;}const token=++recordToken;try{const got=await navigator.mediaDevices.getUserMedia({audio:true});if(disposed||token!==recordToken){got.getTracks().forEach(t=>t.stop());return;}stream=got;const chunks=[];const recorder=new MediaRecorder(got);recording=recorder;recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};recorder.onstop=()=>{got.getTracks().forEach(t=>t.stop());if(disposed)return;const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});releaseMedia(slot);const url=URL.createObjectURL(blob);urls.add(url);media.set(slot,{url,name:`caisik-${slot}.${blob.type.includes('mp4')?'m4a':'webm'}`});if(recording===recorder)render();feedback('Nahrávka připravená pouze pro tuto relaci. Stáhni ji, chceš-li ji zachovat.');};recorder.start();const status=root.querySelector('.ws-record-status');if(status)status.textContent=`NAHRÁVÁ SE ${slot==='takeA'?'A':'B'} — mikrofon je aktivní. Zastav ho tlačítkem níže.`;}catch{stream?.getTracks().forEach(t=>t.stop());stream=null;feedback('Přístup k mikrofonu nebyl získán. Můžeš vybrat vlastní audio soubor.');}}
  function compare(){const id=drafts[active].artifactId;const artifact=(store.get().artifacts||[]).find(a=>a.id===id);const target=root.querySelector('[data-comparison]');if(!artifact?.versions?.length){feedback('Nejdřív ulož první verzi projektu.');return;}const first=artifact.versions[0],last=artifact.versions.at(-1);target.innerHTML=`<div class="ws-two ws-comparison"><article><h4>PRVNÍ / ${e(new Date(first.createdAt).toLocaleString('cs-CZ'))}</h4><pre>${e(first.text)}</pre><p data-i18n-user>${e(first.decision)}</p></article><article><h4>POSLEDNÍ / ${artifact.versions.length} VERZÍ</h4><pre>${e(last.text)}</pre><p data-i18n-user>${e(last.decision)}</p></article></div>`;}
  function save(){const d=drafts[active];const error=validateWork(active,d);if(error){feedback(error);return;}const now=new Date().toISOString(),id=d.artifactId||`work-${uid()}`;const snapshot={active,...copy(drafts),[active]:{...copy(d),artifactId:id}};const version={id:uid(),createdAt:now,text:buildWorkText(active,d),decision:d.decision.trim(),nextStep:d.nextStep.trim(),palette:active==='writer'?copy(d.palette):[],strokes:active==='writer'?normalizeStrokes(d.strokes):[],metadata:{...copy(d),artifactId:id}};const ok=store.update(s=>{let artifact=s.artifacts.find(a=>a.id===id);if(!artifact){artifact={id,discipline:active,title:d.title.trim()||d.word||LABELS[active],createdAt:now,updatedAt:now,versions:[]};s.artifacts.push(artifact);}artifact.versions.push(version);artifact.updatedAt=now;const quest=(s.quests||[]).find(q=>q.discipline===active&&q.type==='main'&&q.status!=='archived'&&(!q.artifactId||q.artifactId===id));if(quest)quest.artifactId=id;artifact.title=d.title.trim()||d.word||artifact.title;s.events.push({id:uid(),type:'artifact-version',artifactId:id,discipline:active,createdAt:now});s.drafts.workshops=applyWorkshopDelta(s.drafts.workshops||{},baseline,snapshot);});if(store.get().artifacts.some(a=>a.id===id))d.artifactId=id;if(ok){baseline=copy(snapshot);dirty=false;feedback('Vlastní verze uložená. V Blackbooku zůstává první pokus i každá vysvětlená revize.');compare();}else feedback('Zápis se nepodařil potvrdit. Tvůj pokus zůstává na stránce; vyexportuj jej před zavřením.');}
  listen(root,'input',event=>{const el=event.target,d=drafts[active];if(el.dataset.field){d[el.dataset.field]=el.value;if(el.dataset.field==='text'&&active==='mc'){const preview=root.querySelector('[data-reading]');if(preview)preview.innerHTML=markedText(el.value);const count=root.querySelector('.ws-count');if(count)count.textContent=`${lineCount(el.value)} řádků / záměr ${e(d.target)}. Počet řádků není skóre kvality.`;}if(el.dataset.field==='symbol'){const symbol=root.querySelector('[data-symbol]');if(symbol)symbol.textContent=el.value;}if(['layer','scale'].includes(el.dataset.field))draw();schedule();}if(el.dataset.palette!==undefined){d.palette[Number(el.dataset.palette)].purpose=el.value;schedule();}if(el.dataset.paletteColor!==undefined){d.palette[Number(el.dataset.paletteColor)].color=el.value;schedule();render();}if(el.dataset.energy!==undefined){d.energy[Number(el.dataset.energy)]=Number(el.value);drawEnergy();schedule();}});
  listen(root,'change',event=>{const el=event.target;if(!el.dataset.file)return;const file=el.files?.[0];if(!file)return;if(file.size>180*1024*1024){feedback('Pro tuto lokální relaci vyber soubor menší než 180 MB.');return;}const video=el.dataset.file.startsWith('phrase');if(!(video?file.type.startsWith('video/'):file.type.startsWith('audio/'))){feedback('Vyber odpovídající zvukový nebo video soubor.');return;}releaseMedia(el.dataset.file);const url=URL.createObjectURL(file);urls.add(url);media.set(el.dataset.file,{url,name:file.name});render();feedback('Vlastní soubor otevřen pouze v této relaci. Nikam se neodesílá.');});
  listen(root,'pointerdown',event=>{if(!event.target.closest('.ws-sketch'))return;const svg=root.querySelector('.ws-sketch');if(startStroke(point(event))){pointer=event.pointerId;svg.setPointerCapture(pointer);draw();event.preventDefault();}});
  listen(root,'pointermove',event=>{if(event.pointerId!==pointer||!stroke)return;if(drafts.writer.strokes.reduce((n,s)=>n+s.points.length,0)>=MAX_POINTS){endStroke();return;}stroke.points.push(point(event));draw();});
  listen(root,'pointerup',endStroke);listen(root,'pointercancel',endStroke);
  listen(root,'keydown',event=>{if(!event.target.classList?.contains('ws-sketch'))return;const delta={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]}[event.key];if(delta){event.preventDefault();keyboardPoint=[clamp(keyboardPoint[0]+delta[0],0,900),clamp(keyboardPoint[1]+delta[1],0,440)];if(stroke){stroke.points.push([...keyboardPoint]);if(stroke.points.length>=MAX_POINTS)endStroke();}const cursor=root.querySelector('[data-cursor]');const scale=Number(drafts.writer.scale)||1;cursor.setAttribute('cx',450*(1-scale)+keyboardPoint[0]*scale);cursor.setAttribute('cy',220*(1-scale)+keyboardPoint[1]*scale);cursor.setAttribute('opacity','1');draw();}if(event.key===' '){event.preventDefault();if(stroke)endStroke();else startStroke([...keyboardPoint]);draw();}if(event.key==='Escape')endStroke();});
  listen(root,'focusout',event=>{if(event.target.classList?.contains('ws-sketch'))endStroke();});
  listen(root,'click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.letter!==undefined){const key=b.dataset.letter;if(!drafts.writer.alphabet?.[key])return;if(drafts.writer.strokes.length&&!globalThis.confirm('Načíst vlastní uložené písmeno? Aktuální neuložená skica se nahradí; uložené verze zůstanou.'))return;stopReplay();drafts.writer.strokes=normalizeStrokes(drafts.writer.alphabet[key]);drafts.writer.word=key;schedule();render();feedback('Načtena tvoje dříve uložená konstrukce písmene.');return;}if(b.dataset.discipline){endStroke();flush();recordToken++;stopRecording();active=b.dataset.discipline;schedule();render();return;}const action=b.dataset.action,d=drafts[active];if(!action)return;
    if(action==='save')save();if(action==='compare')compare();
    if(action==='newProject'){if(!globalThis.confirm('Začít nový projekt? Uložené verze zůstanou. Rozepsaný návrh v této dílně se vyprázdní.'))return;drafts[active]=initial(active);schedule();render();}
    if(action==='undo'){stopReplay();d.strokes.pop();schedule();draw();}
    if(action==='clear'){if(!globalThis.confirm('Smazat pouze aktuální skicu? Uložené verze v Blackbooku zůstanou.'))return;stopReplay();d.strokes=[];schedule();draw();}
    if(action==='stopReplay'){stopReplay();draw();}
    if(action==='replay'){stopReplay();const total=d.strokes.reduce((n,s)=>n+s.points.length,0);if(!total){feedback('Nejdřív vytvoř vlastní tahy.');return;}if(reduced.matches||store.get().settings.motion!=='full'||document.documentElement.dataset.motion==='off'){draw();feedback('Klidný režim: zobrazena dokončená fáze.');return;}const start=performance.now();b.textContent='PŘEHRÁVÁ SE POŘADÍ TVÝCH TAHŮ';const frame=now=>{if(reduced.matches||document.documentElement.dataset.motion==='off'||root.hidden){stopReplay();draw();return;}const progress=Math.min(1,(now-start)/Math.min(8000,1200+total*4));draw(Math.ceil(total*progress));if(progress<1&&!document.hidden)replayFrame=requestAnimationFrame(frame);else{stopReplay();draw();}};replayFrame=requestAnimationFrame(frame);}
    if(action==='downloadSvg'){const paths=d.strokes.map(s=>`<path d="${strokePath(s.points)}" stroke="${s.color}" stroke-width="${s.width}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`).join('');download('caisik-vlastni-skica.svg',`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 440"><title>${e(d.word||'Vlastní skica CAISIK')}</title>${paths}</svg>`,'image/svg+xml');feedback('Připraven transparentní SVG export vlastních tahů.');}
    if(action==='alphabet'){const letter=d.word.trim();if(!letter||letter.length>4){feedback('Do pole slovo napiš jedno až čtyři písmena pro vlastní abecedu.');return;}if(!d.strokes.length){feedback('Písmeno nejdřív nakresli.');return;}d.alphabet={...d.alphabet,[letter]:copy(d.strokes)};schedule();render();feedback('Vlastní konstrukce uložená do abecedy tohoto návrhu.');}
    if(action==='drawWords'){const items=(store.get().inventory||[]).map(x=>x.text||x.content||x.title||x.word).filter(nonempty);const chosen=[];while(items.length&&chosen.length<3)chosen.push(items.splice(Math.floor(Math.random()*items.length),1)[0]);root.querySelector('[data-prompts]').textContent=chosen.join(' / ')||'Inventář je zatím prázdný. Zachyť si vlastní podněty.';}
    if(action==='replaceLine'){if(!nonempty(d.oldLine)||!nonempty(d.newLine)){feedback('Vyplň původní i upravený řádek.');return;}const lines=d.text.split('\n'),index=lines.indexOf(d.oldLine);if(index<0){feedback('Původní řádek se v textu přesně neshoduje. Nic se nepřepsalo.');return;}lines[index]=d.newLine;d.text=lines.join('\n');schedule();render();feedback('Přesný řádek nahrazen. Vysvětli změnu a ulož novou verzi.');}
    if(action==='record-A')record('takeA');if(action==='record-B')record('takeB');if(action==='stopRecord'){recordToken++;stopRecording();}
    if(action.startsWith('delete-')){releaseMedia(action.slice(7));render();feedback('Soubor odebrán z této relace. Původní soubor v zařízení se nemění.');}
    if(['markCue','listenA','listenB','seekA','seekB'].includes(action)){const audio=media.get('mix')?.element;if(!audio){feedback('Nejdřív vyber vlastní mix.');return;}if(action==='markCue'){const time=audio.currentTime;d.cues+=`${d.cues?'\n':''}${Math.floor(time/60)}:${String(Math.floor(time%60)).padStart(2,'0')} — moje rozhodnutí: `;schedule();render();}if(action==='listenA'||action==='listenB'){d[action==='listenA'?'pointA':'pointB']=audio.currentTime;schedule();feedback(`Čas ${action==='listenA'?'A':'B'} uložen: ${audio.currentTime.toFixed(1)} s.`);}if(action==='seekA'||action==='seekB'){const time=d[action==='seekA'?'pointA':'pointB'];if(!Number.isFinite(time)){feedback('Nejdřív si zapamatuj příslušný čas.');return;}audio.currentTime=time;audio.play().catch(()=>feedback('Přehrávání spusť ovladačem audio přehrávače.'));}}
    if(action==='useSymbol'){if(!nonempty(d.symbol)||!nonempty(d.meaning)){feedback('Napiš znak i jeho vlastní význam.');return;}const ok=store.update(s=>{s.profile.symbol=d.symbol;});feedback(ok?'Tvůj znak je nyní osobní avatar.':'Znak zůstává v paměti této stránky; trvalý zápis se nepodařil potvrdit.');}
  });
  function suspend(){recordToken++;flush();stopRecording();stopReplay();media.forEach(item=>item.element?.pause());draw();}
  const hiddenObserver=window.MutationObserver?new window.MutationObserver(()=>{if(root.hidden)suspend();}):null;hiddenObserver?.observe(root,{attributes:true,attributeFilter:['hidden']});
  if(typeof reduced.addEventListener==='function')listen(reduced,'change',()=>{if(reduced.matches){stopReplay();draw();}});
  listen(window,'caisik:panel',event=>{if(event.detail?.panel!=='workshop')suspend();});
  listen(window,'caisik:discipline',event=>{const id=event.detail?.discipline;if(!DISCIPLINES.includes(id)||id===active)return;endStroke();flush();recordToken++;stopRecording();active=id;schedule();render();});
  listen(window,'pagehide',()=>{flush();stopRecording();stopReplay();});listen(document,'visibilitychange',()=>{if(document.hidden){stopRecording();stopReplay();draw();}});
  render();
  return ()=>{disposed=true;recordToken++;flush();hiddenObserver?.disconnect();controller.abort();disposers.forEach(dispose=>dispose());stopRecording();stopReplay();media.forEach((_,key)=>releaseMedia(key));urls.forEach(url=>URL.revokeObjectURL(url));urls.clear();};
}
